# robust: find '"grid": [...]' and parse balanced brackets
def extract_grids(s):
    out=[]
    for mm in _re.finditer(r'"grid":\s*', s):
        p = mm.end()
        if s[p] != '[': continue
        depth=0; q=p
        while q < len(s):
            if s[q]=='[': depth+=1
            elif s[q]==']':
                depth-=1
                if depth==0: break
            q+=1
        try: out.append(json.loads(s[p:q+1]))
        except Exception as e: out.append(('FAIL',s[p:p+50]))
    return out

